\label{teobigpi}
		Let $\Omega\subset{\mathbb R}^{n+1}$ be a bounded $C_1$-chord-arc domain and let $\mathcal{L} \in\mathcal{E}_{\rm DMO}({\mathbb R}^{n+1})$. Let $p\in (1,2)$, suppose that $(R_q)_{\mathcal L}$ is solvable in $\Omega$ for some $q>p$, and that $\partial\Omega$ supports a weak $p$-Poincar\'e inequality. 
		Suppose that for every $\xi\in{\partial\Omega}$ and $0<r\leq{\rm diam}({\partial\Omega})$
		there exists a $C_2$-chord-arc domain $U_{\xi,r}$ such that $ B(\xi,r) \cap \Omega \subset U_{\xi,r}$, $(N_q)_{\mathcal L}$ is solvable in $U_{\xi,r}$ uniformly on $\xi$ and $r$, and
		\begin{equation}\label{eqbigpiece}
			{\mathcal H}^n(B(\xi,r)\cap {\partial\Omega}\setminus \partial U_{\xi,r})\leq {\varepsilon}\,r^n,
		\end{equation}
		for some ${\varepsilon}>0$.
		If  ${\varepsilon}>0$ is small enough (depending only on $n$, $C_1$, $C_2$, the solvability of 
		$(R_q)_{\mathcal L}$ in $\Omega$, and the uniform solvability of $(N_q)_{\mathcal L}$  in the domains $U_{\xi,r}$), then $(N_p)_{\mathcal L}$ is solvable in $\Omega$.

\label{corobigpi}
		Let $\Omega\subset{\mathbb R}^{n+1}$ be a bounded $C_1$-chord-arc domain. Let $p\in (1,2)$, suppose that $(R_q)_\Delta$ is solvable in $\Omega$ for some $q>p$, and that $\partial\Omega$ supports a weak $p$-Poincar\'e inequality. 
		Suppose that for every $\xi\in{\partial\Omega}$ and $0<r\leq{\rm diam}({\partial\Omega})$
		there exists a Lipschitz domain $U_{\xi,r}$ (with Lipschitz character uniform on $\xi$ and $r$) such that $ B(\xi,r) \cap \Omega \subset U_{\xi,r}$ and
		\begin{equation}\label{eqbigpiece''}
			{\mathcal H}^n(B(\xi,r)\cap {\partial\Omega}\setminus \partial U_{\xi,r})\leq {\varepsilon}\,r^n,
		\end{equation}
		for some ${\varepsilon}>0$.
		If  ${\varepsilon}>0$ is small enough (depending only on $n$, the solvability of 
		$(R_q)_\Delta$ in $\Omega$, and the Lipschitz character of $U_{\xi,r}$), then $(N_p)_\Delta$ is solvable in $\Omega$.

\label{lem:HMT vs Hajlasz}
		Let $\Omega \subset {\mathbb R}^{n+1}$ be a bounded open set with an Ahlfors regular boundary.  Then,   it holds that $ M^{1,p}({\partial\Omega}) \subset  W^{1,p}(\partial^* \Omega)$ and, for any $f \in  M^{1,p}({\partial\Omega})$ and  $ j ,k \in \{1, \dots, n+1\}$,  
		\begin{equation}\label{eq:M emb W}
			\| \partial_{t,j,k} f\|_{L^p(\partial^*\Omega)} \lesssim \| \nabla_H f\|_{L^p({\partial\Omega})},
		\end{equation}
		where the implicit constant depends on $n$ and the Ahlfors regularity constants.

\label{lem:denseLorentz}
		Let $\mu$ be an Ahlfors $n$-Ahlfors regular measure in ${\mathbb R}^{n+1}$ and $X=\operatorname{supp}\mu$.
		For   $1<p <\infty$, and $1\leq q <\infty$,  $\mathop\mathrm{Lip}(X)$  is dense in $L^{p,q}(\mu)$. Moreover,  $\mathop\mathrm{Lip}_0(X)$ is dense in $L_0^{p,q}(\mu)$ for $p \in (1,\infty)$ and $q \in[1,p]$.

\label{thm:trace-extension}
		If  $\Omega\subset {\mathbb R}^{n+1}$ is a uniform domain with $n$-Ahlfors regular boundary, there exists a bounded linear trace operator $\textup{Tr}_{\Omega \to {\partial\Omega}}: W^{1,2}(\Omega) \to H^{1/2}({\partial\Omega})$ and a bounded linear extension operator $\textup{Ext}_{{\partial\Omega} \to \Omega}: H^{1/2}({\partial\Omega}) \to W^{1,2}(\Omega) $ such that 
		\begin{align}\label{eq:trace}
			\| \textup{Tr}_{\Omega \to {\partial\Omega}}  (u) \|_{H^{1/2}(\Omega)} &\leq C_T\, \| u\|_{W^{1,2}(\Omega)}\\
			\| \textup{Ext}_{{\partial\Omega} \to \Omega} (f)\|_{W^{1,2}(\Omega )}  &\leq  C_E\,  \| f \|_{H^{1/2}({\partial\Omega})}.\label{eq:extension}
		\end{align} 
		Moreover, $\textup{Ext}_{{\partial\Omega} \to \Omega} \circ \textup{Tr}_{\Omega \to {\partial\Omega}} = \textup{Id}$, the identity on $H^{1/2}({\partial\Omega})$.

\label{teomoser}
