	\!\int_{B\cap\Omega} u\,dm$.
		Further, there exists some $\alpha>0$ such that for $0<{\varepsilon}\leq 1$,
		\begin{equation}\label{eq:moser2}
			{\rm osc}_{{\varepsilon} B}(u) \leq C\,{\varepsilon}^\alpha \,{\rm osc}_B(u).
		\end{equation}
		The constants $C$ and $\alpha$ in {(\ref{eq:moser1})} and {(\ref{eq:moser2})} depend only on $n$, the ellipticity of $A$, the Ahlfors regularity of ${\partial\Omega}$, and  the uniformity  constant of $\Omega$.

\label{teoneumann1}
		Let $\Omega\subset{\mathbb R}^{n+1}$ be a bounded uniform  domain with Ahlfors regular boundary and let ${\mathcal L} \in {\mathcal E}(\Omega)$.
		There exists a unique function $N:\overline\Omega\times \overline\Omega\to {\mathbb R}\cup\{+\infty\}$ (called the Neumann function) such that  the following holds:
		\begin{itemize}
			\item[(i)] $N(x,\cdot)\in W^{1,2}(\Omega\setminus\{x\}) \cap C(\overline\Omega\setminus\{x\})$,  for any fixed $x\in\Omega$, 
			\item[(ii)] $\int_{\partial\Omega} N(x,\xi)\,d\sigma(\xi)=0$, 
			\item[(iii)] For any $y\in\overline \Omega$ and $v\in W^{1,2}(\Omega)$,
			$$\int_\Omega A(x)\,\nabla_1N(x,y)\cdot \nabla v(x)\,dx = v(y) - \;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{\partial\Omega} v\,d\sigma,$$
			where we identified $v$ on ${\partial\Omega}$ with the trace of $v$.
			\item[(iv)] For any $x,y\in\Omega$, $N^T(x,y) = N(y,x)$, where $N^T$ is the Neumann function for the adjoint operator  ${\mathcal L}^*$ on $\Omega$.
			\item[(v)] For all $x,y\in\overline\Omega$,
			$$|N(x,y)|\leq \frac{C}{|x-y|^{n-1}}.$$
			\item[(vi)] There exists some $\alpha\in (0,1)$ such that for all $x,x'\in\overline\Omega$, $y\in\Omega$,
			$$|N(x,y) - N(x',y)| \leq \frac{C\,|x-x'|^\alpha}{|x-y|^{n-1+\alpha} + |x'-y|^{n-1+\alpha} }.$$
		\end{itemize}
		The constants $C$ in (v) and (vi) only depend on the uniformity constants of $\Omega$.

\label{teoneumann2}
		Under the assumptions of Theorem \ref{teoneumann1}, for any $g\in L^\infty_0({\partial\Omega})$, there exists a unique function  $u\in {\widehat{W}}^{1,2}(\Omega)$ which solves the Neumann problem {(\ref{eqneumann1})} with the following representation:
		$$u(x) = \int_{\partial\Omega} N(x,\xi)\,g(\xi)\,d\sigma(\xi),\quad\mbox{ for all $x\in\Omega$.}
		$$

\label{propoloc0}
		Under the assumptions of Theorem \ref{teoneumann1}, let ${\varphi}\in C_c^\infty({\mathbb R}^{n+1})$, let $g\in L^\infty_0({\partial\Omega})$, and  let  $u\in \widehat W^{1,2}(\Omega)$ solve the Neumann problem {(\ref{eqneumann1})}.  For all $x\in \Omega$, we have
		\begin{align*}
			{\varphi}(x)\,u(x) - \;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{\partial\Omega} {\varphi}\,u\,d\sigma &= \int_{\partial\Omega} N(x,\xi)\,{\varphi}(\xi)\,g(\xi)\,d\sigma(\xi) + \int_\Omega u(y)\,A(y)\,\nabla {\varphi}(y)\cdot \nabla_2 N(x,y)\,dy \\
			& \quad- \int_\Omega N(x,y)\,A(y)\nabla u(y)\cdot\nabla{\varphi}(y)\,dy.
		\end{align*}

Set $v={\varphi}\,u$. By   Theorem \ref{teoneumann1} (iii) applied to  ${\mathcal L}^*$ and $N^T$, and (iv), we have  that
		$$v(x) - \;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{\partial\Omega} v\,d\sigma= \int_\Omega A^T(y)\,\nabla_2N(x,y)\cdot \nabla v(y)\,dy =\int_\Omega A(y)\nabla v(y)\cdot\nabla_2N(x,y)\,dy.$$
		Writing $N^x = N(x,\cdot)$, we have
		\begin{align}\label{eqalk471}
			\int_\Omega A(y)&\nabla v(y)\cdot\nabla_2N(x,y)\,dy  =   \int_\Omega u\,A\nabla {\varphi}\cdot\nabla N^x\,dm + \int_\Omega {\varphi}\,A\nabla u\cdot\nabla N^x\,dm\\
			& = 
			\int_\Omega u\,A\nabla {\varphi}\cdot\nabla N^x\,dm + \int_\Omega A\nabla u\cdot\nabla ({\varphi}\,N^x)\,dm - \int_\Omega N^xA\nabla u\cdot\nabla{\varphi}\,dm.\nonumber
		\end{align}
		By {(\ref{eqweak93})} with ${\varphi}$ replaced by ${\varphi}\,N^x$, Theorem \ref{teoneumann1} (i),  and a standard approximation argument, we infer that 
		$$\int_\Omega A\nabla u\cdot\nabla ({\varphi}\,N^x)\,dm = 
		\int_{\partial\Omega} N^x\,{\varphi}\,g\,d\sigma.$$
		The lemma readily  follows once we plug this identity into {(\ref{eqalk471})}.

\label{propodual1}
		Let $\Omega$ be a bounded chord-arc domain and ${\mathcal L} \in {\mathcal E}(\Omega)$.  Suppose that $1 < p < \infty$ and that $(R_q)_{\mathcal L}$ is solvable for some $q > p$. The following hold:
		\begin{itemize}
			\item[(a)] If $(N_p)_{\mathcal L}$ (resp. $(N_{L^{p,1},L^p})_{\mathcal L}$) is solvable, then $(N^R_{p'})_{{\mathcal L}^*}$ (resp. $(N^R_{L^{p'},L^{p',\infty}})_{{\mathcal L}^*}$) is solvable.
			\item[(b)] If $(N^R_{p'})_{{\mathcal L}^*}$ (resp. $(N^R_{L^{p'},L^{p',\infty}})_{{\mathcal L}^*}$) is solvable and we assume,  in addition,  that $\partial \Omega$ supports a weak $p$-Poincaré inequality, then  $(N_p)_{\mathcal L}$ (resp. $(N_{L^{p,1},L^p})_{\mathcal L}$) is also solvable.
		\end{itemize}
		Further, 
		$$C_{\mathcal L}(N_p)\approx C_{{\mathcal L}^*}(N^R_{p'})\qquad \text{and}\qquad C_{\mathcal L}(N_{L^{p,1},L^p})\approx C_{{\mathcal L}^*}(N^R_{L^{p'},L^{p',\infty}}).$$

\label{lemfinit}
		Let $\Omega\subset{\mathbb R}^{n+1}$ be a bounded chord-arc domain and let $\rho\in (0,{\rm diam}({\partial\Omega})]$.  Then $(N_{p}^R(\rho))_{\mathcal L}$ is solvable for any  $1<p<\infty$  with constant
		$$ C_{\mathcal L}(N^R_{p}(\rho))\lesssim \frac{{\rm diam}({\partial\Omega})}\rho.$$

\label{teotrace**}
		Let \(\Omega \subset \mathbb{R}^{n+1}\) be a  uniform domain and let  \(B := B(x_0, R)\) be a ball of radius \(R > 0\) centered at \(x_0 \in \partial \Omega\).  There exists a constant \(C > 2\), depending only on the uniformity constants of \(\Omega\),  such that if  \(u \in W^{1,p}(C B \cap \Omega)\), for \(1 < p <n+1\),  then
		\begin{equation}\label{eq:Poincare-interior}
			\bigg(\;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{B\cap\Omega} |u-u_B|^{p+{\varepsilon}_p}\,dm\bigg)^{\frac1{p+{\varepsilon}_p}}\\
			\lesssim   R\left(\;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{CB\cap\Omega}|\nabla u|^p \,dm\right)^{\frac1p},
		\end{equation}
		where  \(u_B := \;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{B \cap \Omega} u \, dm\) and ${\varepsilon}_{p}$ is some positive constant depending only on $p$ and $n$.

Since \eqref{eq:Poincare-interior} is scale invariant, we may assume that  \(R = 1\). If \(T_\Delta \subset \Omega\) is the Carleson box associated with the surface ball \(\Delta := B \cap \partial \Omega\) (see \cite[Eq. 3.59]{HM} for its definition), then by \cite[Eq. (3.60)]{HM}, we have \(\frac{5}{4} B \cap \Omega \subset T_\Delta \subset CB \cap \Omega\) for some large constant \(C > 2\) depending only on the uniformity constants of \(\Omega\).   Furthermore, according to \cite[Lemma 3.61]{HM}, \(T_\Delta\) is a uniform domain, where the uniformity constants depend only on those of \(\Omega\) and are uniform with respect to \(B\). It is evident that \(\text{diam}(T_\Delta) \approx 1\).


		By \cite[Theorem 2]{Jo},  any uniform domain is a Sobolev extension domain for the homogeneous Sobolev space $\dot W^{1,p}$ for any  $p \in (1, \infty)$.  Therefore,  since $u \in \dot W^{1,p}(T_\Delta)$,  we may extend it to a function $ {\widetilde{u}}\in \dot W^{1,p}({\mathbb R}^n)$, satisfying   $\| \nabla {\widetilde{u}} \|_{L^{p}({\mathbb R}^{n+1})} \lesssim \|\nabla  u\|_{L^{p}(T_\Delta)}$.   If  $q:= \frac{(n+1)\,p}{n+1-p}$, then by the Sobolev-Poincar\'e inequality,  we have that 
		\begin{align*}
			\bigg(\int_{B\cap\Omega} |u-u_B|^{q}\,dm\bigg)^{1/q} &\leq 2\, \bigg( \int_{CB} |{\widetilde{u}}-{\widetilde{u}}_{CB}|^{q}\,dm\bigg)^{1/q}
			\lesssim   \bigg(\int_{CB}|\nabla {\widetilde{u}}|^p \,dm\bigg)^{1/p}\\
			& \lesssim   \bigg(\int_{T_\Delta}|\nabla u|^p \,dm\bigg)^{1/p} \leq \bigg(\int_{CB\cap \Omega}|\nabla u|^p \,dm\bigg)^{1/p}.
		\end{align*}
		It is trivial to see that \eqref{eq:Poincare-interior} follows by rescaling the  inequalities above.

\label{lemfutur}
		Let \(\Omega \subset \mathbb{R}^{n+1}\) be an open set  with a $n$-Ahlfors regular boundary satisfying the interior corkscrew condition. Then, for all \(p\) and \(q\) such that \(1 \leq q \leq p < q\left(1 + \frac{1}{n}\right)\), any function \(v: \Omega \to \mathbb{R}\), and any ball \(B\) centered at \(\partial \Omega\), we have
		\begin{equation}\label{eqRHI}
			\left(\;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{B \cap \Omega} |v|^p \, dm \right)^{1/p} \lesssim_{p,q} \left(\;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{2B \cap \partial \Omega} |\mathcal{N}_{\Omega,4 r(B)} v|^q \, d\sigma \right)^{1/q},
		\end{equation}
		assuming the aperture of the cones associated with \(\mathcal{N}_{\Omega}\) is large enough, depending only on \(n\).

Consider first the case $q=1$.
		Denote by $W_{B}$ the family of (Euclidean) Whitney cubes of $\Omega$ that intersect $B \cap \Omega$.
		Adjusting suitably the parameters of the construction of the Whitney cubes, we can ensure that 
		the cubes $P\in W_{B}$ satisfy
		$${\rm diam}(P)\leq r(B)/2\quad \text{ and }\quad P\subset 2B\cap \Omega.$$
		Denote $\Delta=B\cap{\partial\Omega}$. Then we write
		\begin{align*}
			\left(\;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{B \cap \Omega} |v|^p\,dm\right)^{1/p}\!\!\sigma(\Delta) & \lesssim \bigg( \sum_{P\in W_B} m_P(|v|^p)\,\ell(P)^{n+1}\bigg)^{1/p}\frac{\sigma(\Delta)}{r(B)^{(n+1)/p}}\\
			& \lesssim 
			\bigg( \sum_{P\in W_B} \inf_{\xi\in {\widehat{P}}} {\mathcal N}_{\Omega,4 r(B)}(v)(\xi)^p\,\ell(P)^{n+1}\bigg)^{1/p}\frac{\sigma(\Delta)}{r(B)^{(n+1)/p}},
		\end{align*}
		where $m_P$ denotes the mean with respect to Lebesgue measure and ${\widehat{P}}\in{\mathcal D}_{\partial\Omega}$ is a boundary cube associated with $P$ such that ${\rm dist}({\widehat{P}},P)\approx \ell(P)$ and $\ell({\widehat{P}}) = \ell(P)$.
		Observe that we can assume that ${\widehat{P}}\subset 2B$.
		Thus, taking into account that $\frac{n+1}{p} - n>0$ (because $p<1+\frac1n$ as $q=1$), 
		\begin{align}\label{eqfutur}
			\left(\frac1{r(B)^{n+1}}\int_{\Omega\cap B}
			|v|^p\,dm\right)^{1/p}\!\!\sigma(\Delta) & \lesssim 
			\sum_{P\in W_B}
			\inf_{\xi\in {\widehat{P}}} {\mathcal N}_{\Omega,4 r(B)}(v)(\xi)\,\ell(P)^{(n+1)/p}\frac{\sigma(\Delta)}{r(B)^{(n+1)/p}}\\
			& \lesssim
			\sum_{\substack{{\widehat{P}}\in {\mathcal D}_{\partial\Omega}:{\widehat{P}}\subset 2B\\ {\rm diam}(P)\leq r(B)}} \int_{{\widehat{P}}} {\mathcal N}_{\Omega,4r(B)}(v)\,d\sigma \,\frac{\ell(P)^{\frac{n+1}{p} - n}}{r(B)^{\frac{n+1}{p} - n}}\nonumber\\

			&\lesssim \int_{2\Delta}  {\mathcal N}_{\Omega,4 r(B)}(v)\,d\sigma.\nonumber
		\end{align}

		In the case $q>1$, we apply {(\ref{eqfutur})} to the function $u=|v|^q$. Then, for $1\leq s< 1+\frac1n$, we get
