		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{2B \cap {\partial\Omega}} |{\mathcal N}_{\Omega,4 r(B)}(v)|^q\,d\sigma.$$
		Writing $p=sq$, we are done.

\label{lemlocLp**}
		Let $\Omega\subset{\mathbb R}^{n+1}$ be a chord-arc domain and $1<p\leq2$, $0<\rho\leq {\rm diam}({\partial\Omega})$. Suppose that $(N_{L^{p,1},L^p}(\rho))_{\mathcal L}$ 
		and $(D_{L^{p',\infty}})_{{\mathcal L}^*}$ are solvable in $\Omega$. Let $R\geq 4\rho$,  
