		\subsection*{\bf Final estimates for $T_l$}
		Gathering the estimates obtained for $I_{1,a}$ and $I_{1,b}$, we get
		$$
		I_{1}\leq I_{1,a} + I_{1,b} \lesssim {\widetilde{C}}_q\,C(K)\int_Q {\mathcal M}_{\sigma,p'}g\,d\sigma + C_*
		\,(K^{-\alpha} + C(K)\,{\varepsilon}^{a_0})\int_{Q} {\mathcal M}_{\sigma,p'}g\,d\sigma.
		$$
		Combining this with {(\ref{eqtl*})} and {(\ref{eqI2})}, we derive
		\begin{align*}
			\lambda\,T_l \lesssim \lambda\,(I_1+I_2) & \lesssim
			{\widetilde{C}}_q\,C(K)\int_Q {\mathcal M}_{\sigma,p'}g\,d\sigma + C_*\,(K^{-\alpha} + C(K)\,{\widetilde{C}}_q\,{\varepsilon}^{a_0})\int_{Q} {\mathcal M}_{\sigma,p'}g\,d\sigma
			\\
			&\quad+ C_*\,C(K)\,{\varepsilon}^{1/p}\int_{Q} {\mathcal M}_{\sigma,p'}g\,d\sigma\\
			& \lesssim {\widetilde{C}}_q\,C(K)\int_Q {\mathcal M}_{\sigma,p'}g\,d\sigma + C_*\,(K^{-\alpha} + C(K)\,{\widetilde{C}}_q\,{\varepsilon}^{a_1})\int_{Q} {\mathcal M}_{\sigma,p'}g\,d\sigma,
		\end{align*}
		where $a_1=\min(a_0,\frac1{p})$.

		{\vspace{2mm}}
		\subsection*{\bf End of the proof}
		The above bound  for $T_l$ in conjunction with the one in {(\ref{eqcas00})} and the one for $T_f$ in {(\ref{eqtf94})},  implies
		$$\lambda( T_l + T_f) \lesssim
		{\widetilde{C}}_q\,C(K)\int_Q {\mathcal M}_{\sigma,p'}g\,d\sigma + C_*\,C(K)\,{\widetilde{C}}_q\,{\varepsilon}^{a_1}\!\int_{Q} {\mathcal M}_{\sigma,p'}g\,d\sigma
		+C_*\,K^{-\alpha}\!\int_{Q} {\mathcal M}_{\sigma,p'}g\,d\sigma.
		$$
		Recalling {(\ref{eqEQ2})}, we conclude that
		$$\sigma(E_Q) \lesssim 
		\frac1\lambda\,\big( 
		{\widetilde{C}}_q\,C(K)+ C_*\,C(K)\,{\widetilde{C}}_q\,{\varepsilon}^{a_1}
		+C_*\,K^{-\alpha}\big) \int_{Q} {\mathcal M}_{\sigma,p'}g\,d\sigma.
		$$
		Notice that, if we denote
		$$\gamma(K,{\varepsilon}) := C(K)\,{\widetilde{C}}_q\,{\varepsilon}^{a_1}+K^{-\alpha},$$
		then $\gamma(K,{\varepsilon})$ can be taken arbitrarily small, first choosing $K$ large enough and then ${\varepsilon}$ small enough.
		In this way, we have
		\begin{align*}
			\sigma(V_{A\lambda}) = \sum_{Q\in{\mathcal W}_\lambda}
			\sigma(E_Q) & \lesssim 
			\frac1\lambda\,\big( 
			{\widetilde{C}}_q\,C(K)  + C_*\,\gamma(K,{\varepsilon})\big) \sum_{Q\in{\mathcal W}_\lambda}\int_{Q} {\mathcal M}_{\sigma,p'}g\,d\sigma\\
			& = \frac1\lambda\,\big( 
			{\widetilde{C}}_q\,C(K) + C_*\,\gamma(K,{\varepsilon})\big) \int_{V_\lambda} {\mathcal M}_{\sigma,p'}g\,d\sigma.
		\end{align*}
		By  Kolmogorov's inequality and the weak $(p',p')$ boundedness of ${\mathcal M}_{\sigma,p'}$, we obtain 
		$$ \frac1\lambda\int_{V_\lambda} {\mathcal M}_{\sigma,p'}g\,d\sigma \lesssim \frac1\lambda\,\sigma(V_\lambda)^{1/p}\,\|{\mathcal M}_{\sigma,p'}g\|_{L^{p',\infty}({\partial\Omega})}
		\lesssim \frac1\lambda\,\sigma(V_\lambda)^{1/p}\,\|g\|_{L^{p'}({\partial\Omega})}.$$
		Using the inequality $a^{1/p}\,b^{1/p'}\leq \frac ap + \frac b{p'}$ for $a,b>0$, we can write,
		for arbitrary constants $\kappa\in (0,1)$ and   $d>0$, 
		$$\frac d\lambda \int_{V_\lambda} {\mathcal M}_{\sigma,p'}g\,d\sigma 
		\leq \kappa\,\sigma(V_\lambda) + C(\kappa)\,\frac{d^{p'}}{\lambda^{p'}}\,\|g\|_{L^{p'}({\partial\Omega})}^{p'},$$
		with $C(\kappa)$ depending on $p,p'$ besides $\kappa$.
		Therefore, choosing $d={\widetilde{C}}_q\,C(K) + C_*\,\gamma(K,{\varepsilon})$ (and changing $\kappa$ by $C\kappa$ if necessary), we derive
		$$
		\sigma(V_{A\lambda})  \leq  \kappa\,\sigma(V_\lambda) + 
		C(\kappa)\,\frac{{\widetilde{C}}_q^{p'}\,C(K)+  C_*^{p'}\,\gamma(K,{\varepsilon})^{p'}}{\lambda^{p'}}\,\|g\|_{L^{p'}({\partial\Omega})}^{p'}.$$
		Multiplying by $(A\lambda)^{p'}$, we obtain
		$$(A\lambda)^{p'}\,
		\sigma(V_{A\lambda})  \leq  \kappa\,A^{p'}\lambda^{p'}\,\sigma(V_\lambda) + 
		C(\kappa)\,A^{p'}\big({\widetilde{C}}_q^{p'}\,C(K)+  C_*^{p'}\,\gamma(K,{\varepsilon})^{p'}\big)\,\|g\|_{L^{p'}({\partial\Omega})}^{p'},$$
		and,  if we choose $\kappa=1/(2A^{p'})$ and take supremum in $\lambda$,   we deduce
		\begin{align*}
			\sup_{\lambda>0} (\lambda^{p'}\,\sigma(V_\lambda) )=\|{\mathcal M}_\sigma(u) \|_{L^{p',\infty}({\partial\Omega})}^{p'} &\leq \tfrac{1}{2} \|{\mathcal M}_\sigma(u)\|_{L^{p',\infty}({\partial\Omega})} ^{p'}\\ 
			& +  C(A)\big({\widetilde{C}}_q^{p'}\,C(K)+  C_*^{p'}\,\gamma(K,{\varepsilon})^{p'}\big)\,\|g\|_{L^{p'}({\partial\Omega})}^{p'}.
		\end{align*}
		Moving the first term on the right hand side of the inequality above to the left,  this implies that 
		$$
		\|u\|_{L^{p',\infty}({\partial\Omega})}^{p'} \leq C(A)\big({\widetilde{C}}_q^{p'}\,C(K)+  C_*^{p'}\,\gamma(K,{\varepsilon})^{p'}\big)\,\|g\|_{L^{p'}({\partial\Omega})}^{p'}.
		$$


		Since this holds for any Lipschitz function $g\in L^{p'}({\partial\Omega})$ and for all tangent fields $t=t_{j,k}$, we get
		$$C_* ^{p'} \approx C(N^R_{L^{p'},L^{p',\infty}}(\rho))^{p'} \lesssim  C(A)\big({\widetilde{C}}_q^{p'}\,C(K)+  C_*^{p'}\,\gamma(K,{\varepsilon})^{p'}\big).$$
		As remarked above, $\gamma(K,{\varepsilon})$ can be taken arbitrarily small for suitable choices of $K$ and ${\varepsilon}$,  concluding  that
		$$C_* \equiv C_*(\rho) \lesssim C(p,A,K,{\varepsilon})\,{\widetilde{C}}_q,$$
		for suitable choices of $A,K,{\varepsilon}$, uniformly with respect to $\rho\in (0,{\rm diam}({\partial\Omega}))$. This completes the proof of the theorem.

