	\!\int_{B(x,\delta_{{\widetilde{\Omega}}}(x)/2)}|v_{F,\delta} -{\varphi}_{F,\delta}(\xi)|\,dm = 0
		\end{equation}
		for ${\widetilde{\sigma}}$-a.e.\ $\xi\in{\partial{\widetilde{\Omega}}}$ by Lemma \ref{lemdyex9} (c) and {(\ref{eqconv719})}. Further, from the fact that
		$\operatorname{supp}\psi_F\subset\overline{{\widetilde{\Omega}}} \cap \overline{\Omega}\cap 3B$ we infer that $\chi_{{\widetilde{\Omega}}\setminus\Omega}\nabla \psi_F=0$ 
		a.e.\
		with respect to Lebesgue measure, and then by Theorem \ref{teoextMZ} (c), we get
		\begin{align}\label{eqprim57}
			\|{\mathcal C}_{{\widetilde{\Omega}}}(\chi_{{\widetilde{\Omega}}\setminus\Omega}\nabla v_{F,\delta})\|_{L^{q'}({\widetilde{\sigma}})} &\leq \|{\mathcal C}_{{\widetilde{\Omega}}}(\chi_{{\widetilde{\Omega}}\setminus\Omega}\nabla \psi_F)\|_{L^{q'}({\widetilde{\sigma}})}
			+ \|{\mathcal C}_{{\widetilde{\Omega}}}(\nabla u_{F,\delta})\|_{L^{q'}({\widetilde{\sigma}})} \\
			& \lesssim 0 + \|{\varphi}_{F,\delta}-\chi_F\|_{L^{q'}({\widetilde{\sigma}})}
			\leq {\widetilde{\sigma}}(U_\delta(F)\setminus F)^{1/{q'}}\to 0\nonumber
		\end{align}
		as $\delta\to0$. By replacing $v_{F,\delta}$ by $\max(0,\min(1,v_{F,\delta}))$ if necessary, we can ensure that $0\leq v_{F,\delta}\leq 1$ and the
		preceding properties still hold. 


		The function $v_{F,\delta}$ may not extend continuously to $\overline{{\widetilde{\Omega}}}$, and so we cannot choose ${\widetilde{{\varphi}}}_{F,\delta}$
		to be equal to $v_{F,\delta}$. So, inspired by the proof of \cite[Theorem 1.4]{MZ}, we will modify it as follows. Consider the family of Whitney cubes ${\mathcal W}({\widetilde{\Omega}})$ in the
		proof of Lemma \ref{lemdyex9} and the associated partition of $\chi_{{\widetilde{\Omega}}}$ given by the functions $\{\eta_Q\}_{Q\in{\mathcal W}({\widetilde{\Omega}})}$.
		Consider the regularized dyadic extension of ${\varphi}_{F,\delta}$ defined by
		$$h_{F,\delta} = \sum_{Q\in {\mathcal W}({\widetilde{\Omega}})} m_{b(Q),{\widetilde{\sigma}}}({\varphi}_{F,\delta})\,\eta_Q.$$
		Using that ${\varphi}_{F,\delta}$ is Lipschitz in ${\partial{\widetilde{\Omega}}}$, it follows easily that $h_{F,\delta}$ is a Lipschitz extension of ${\varphi}_{F,\delta}$ to $\overline{{\widetilde{\Omega}}}$.

		For a small ${\varepsilon}\ll r(B)$,
		let ${\mathcal W}^{\varepsilon}({\widetilde{\Omega}})$ be the family of the cubes $Q\in{\mathcal W}({\widetilde{\Omega}})$ such that $\ell(Q)\leq {\varepsilon}$ and let $\chi_{\varepsilon}$ be the function
		$$\chi_{\varepsilon} = \sum_{Q\in {\mathcal W}^{\varepsilon}({\widetilde{\Omega}})} \eta_Q.$$
		Notice that $\chi_{\varepsilon}$ is Lipschitz in ${\widetilde{\Omega}}$,  it equals $1$ in  ${\widetilde{\Omega}}\cap U_{c{\varepsilon}}({\partial{\widetilde{\Omega}}})$,  for some $c>0$, and 
		$\operatorname{supp}(\nabla\chi_{\varepsilon})$ is contained in a family of cubes from ${\mathcal W}({\widetilde{\Omega}})$ with side length comparable to ${\varepsilon}$. For some ${\varepsilon}\in (0,\delta)$ to be chosen below, we consider the function in ${\widetilde{\Omega}}$ defined by
		$${\varphi}_{\delta,{\varepsilon}} = \chi_{\varepsilon} \,h_{F,\delta} + (1-\chi_{\varepsilon}) \,v_{F,\delta}.$$
		We also set ${\varphi}_{\delta,{\varepsilon}}={\varphi}_{F,\delta}$ on ${\partial{\widetilde{\Omega}}}$.

		We will check now that we may take ${\widetilde{{\varphi}}}_{F,\delta} = {\varphi}_{\delta,{\varepsilon}}$ in ${\widetilde{\Omega}}$ for some ${\varepsilon}$ small enough. By construction, 
		${\varphi}_{\delta,{\varepsilon}}$ coincides with $h_{F,\delta}$ in a $(c\,{\varepsilon})$-neighborhood of ${\partial{\widetilde{\Omega}}}$ and taking into account that $v_{F,\delta}\in
		{\rm Lip}_{loc}({\widetilde{\Omega}})$, it follows that ${\varphi}_{\delta,{\varepsilon}}$ is Lipschitz in $\Omega$. 
		Also, it is easily checked that $0\leq {\varphi}_{\delta,{\varepsilon}}\leq 1$ and ${\varphi}_{\delta,{\varepsilon}}$ is supported on $\overline{{\widetilde{\Omega}}}\cap 3B$. So
		it just remains to prove that ${\varphi}_{\delta,{\varepsilon}}$ satisfies the properties (b) and (c) of Claim \ref{claimff}.
		First we will show (b), that is,
		${\varphi}_{\delta,{\varepsilon}}\,\chi_{\partial\Omega} \to\chi_F$ in $L^{q'}(\sigma)$ as $\delta\to0$. To this end, we write
		\begin{align*}
			\|{\varphi}_{\delta,{\varepsilon}} - \chi_F\|_{L^{q'}(\sigma)} &= \|{\varphi}_{\delta,{\varepsilon}}\|_{L^{q'}(\sigma|_{{\partial\Omega}\setminus F})}
			\leq 
			\|\chi_{\varepsilon} \,h_{F,\delta}\|_{L^{q'}(\sigma|_{{\partial\Omega}\setminus F})} +\|v_{F,\delta}\|_{L^{q'}(\sigma|_{{\partial\Omega}\setminus {\partial{\widetilde{\Omega}}}})}.
		\end{align*}
		Observe now that $\chi_{\varepsilon} h_{F,\delta}$ is supported in a $(C{\varepsilon})$-neighborhood of $\operatorname{supp}({\varphi}_{F,\delta})$, and so in a 
		$(C'\delta)$-neighborhood of $F$, since ${\varepsilon}\leq\delta$. Hence,
		$$\|\chi_{\varepsilon} \,h_{F,\delta}\|_{L^{q'}(\sigma|_{{\partial\Omega}\setminus F})}\leq \sigma(U_{C'\delta}(F)\setminus F)^{1/q'}\to 0$$
		as $\delta\to0$. On the other hand, since $\psi_F$ vanishes in ${\partial\Omega}\setminus {\partial{\widetilde{\Omega}}}$,
		$$\|v_{F,\delta}\|_{L^{q'}(\sigma|_{{\partial\Omega}\setminus {\partial{\widetilde{\Omega}}}})} = \|\psi_F + u_{F,\delta}\|_{L^{q'}(\sigma|_{{\partial\Omega}\setminus {\partial{\widetilde{\Omega}}}})} = 
		\|u_{F,\delta}\|_{L^{q'}(\sigma|_{{\partial\Omega}\setminus {\partial{\widetilde{\Omega}}}})}.
		$$
		To estimate the last term on the right hand side we apply Lemma \ref{lemaux2} and Theorem \ref{teoextMZ} (b) (recall that
		$u_{F,\delta}$ is a Varopoulos extension of ${\varphi}_{F,\delta}-\chi_F$):
		$$\|u_{F,\delta}\|_{L^{q'}(\sigma|_{{\partial\Omega}\setminus {\partial{\widetilde{\Omega}}}})}\lesssim \|{\mathcal N}_{{\widetilde{\Omega}}}(u_{F,\delta})\|_{L^{q'}({\widetilde{\sigma}})}
		\lesssim \|{\varphi}_{F,\delta}-\chi_F\|_{L^{q'}({\widetilde{\sigma}})}\leq {\widetilde{\sigma}}(U_\delta(F)\setminus F)^{1/q'}\to 0$$
		as $\delta\to0$. This completes of the proof of the fact that $\|{\varphi}_{\delta,{\varepsilon}} - \chi_F\|_{L^{q'}(\sigma)}\to0$.

		{\vspace{2mm}}
		Next we turn our attention to the property (c) in Claim \ref{claimff}.
		We split
		$$\nabla{\varphi}_{\delta,{\varepsilon}} = \nabla\chi_{\varepsilon} (h_{F,\delta} - v_{F,\delta}) + \chi_{\varepsilon} \,\nabla h_{F,\delta}
		+ (1-\chi_{\varepsilon}) \,\nabla v_{F,\delta},$$
		so that
		\begin{align}\label{eqt1t2t3}
			\|{\mathcal C}_{{\widetilde{\Omega}}}(\chi_{{\widetilde{\Omega}}\setminus\Omega}\nabla {\widetilde{{\varphi}}}_{\delta,{\varepsilon}})\|_{L^{q'}({\widetilde{\sigma}})}
			& \leq
			\|{\mathcal C}_{{\widetilde{\Omega}}}(\nabla\chi_{\varepsilon} (h_{F,\delta} - v_{F,\delta}))\|_{L^{q'}({\widetilde{\sigma}})}
			+
			\|{\mathcal C}_{{\widetilde{\Omega}}}(\chi_{\varepsilon} \,\nabla h_{F,\delta})\|_{L^{q'}({\widetilde{\sigma}})}\\
			&\quad +
			\|{\mathcal C}_{{\widetilde{\Omega}}}(\chi_{{\widetilde{\Omega}}\setminus\Omega}\nabla v_{F,\delta})\|_{L^{q'}({\widetilde{\sigma}})} \nonumber\\
			& =: T_1 + T_2+ T_3.\nonumber
		\end{align}
		We have already shown that $T_3\to0$ as $\delta\to 0$ in {(\ref{eqprim57})}. To estimate $T_1$, we write, for $\xi\in {\partial{\widetilde{\Omega}}}$, 
		\begin{align*}
			{\mathcal C}_{{\widetilde{\Omega}}}(\nabla\chi_{\varepsilon} (h_{F,\delta} - v_{F,\delta}))(\xi) & =
			\sup_{r>0} \frac1{r^n}\int_{{\widetilde{\Omega}}\cap B(\xi,r)} |\nabla\chi_{\varepsilon} (h_{F,\delta} - v_{F,\delta})|\,dm \\
			& \lesssim \sup_{r>0} \frac1{{\varepsilon}\,r^n}\int_{{\widetilde{\Omega}}\cap B(\xi,r)\cap \operatorname{supp}(\nabla\chi_{\varepsilon})} |h_{F,\delta} - v_{F,\delta}|\,dm.
		\end{align*}
		Denote by ${\mathcal W}^{({\varepsilon})}({\widetilde{\Omega}})$ the family 
		family of cubes from ${\mathcal W}({\widetilde{\Omega}})$ with side length comparable to ${\varepsilon}$ such that 
		$\operatorname{supp}(\nabla\chi_{\varepsilon})$ is contained in the union of cubes from this family. 
		Also, for a function $u:{\widetilde{\Omega}}\to{\mathbb R}$, $\zeta\in{\partial{\widetilde{\Omega}}}$, and $t>0$, let
		$${\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},t} u(\zeta) = \sup_{x\in\gamma_{{\widetilde{\Omega}}}(\zeta)\cap B(\zeta,t)}\;\mathchoice
	{{\setbox0=\hbox{$\displaystyle{\textstyle-}{\int}$ }
		\vcenter{\hbox{$\textstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\textstyle{\scriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	{{\setbox0=\hbox{$\scriptscriptstyle{\scriptscriptstyle-}{\int}$ }
		\vcenter{\hbox{$\scriptscriptstyle-$ }}\kern-.58\wd0}} 
	\!\int_{B(x,\delta_\Omega(x)/2)}|u|\,dm,$$
		for a cone $\gamma_{{\widetilde{\Omega}}}(\xi)$ with big enough aperture.
		Then, for $0<r\leq {\rm diam}({\widetilde{\Omega}})$, we have
		\begin{align*}
			\frac1{{\varepsilon}\,r^n}\int_{{\widetilde{\Omega}}\cap B(\xi,r)\cap \operatorname{supp}(\nabla\chi_{\varepsilon})} |h_{F,\delta} - v_{F,\delta}|\,dm
			& \leq \frac1{{\varepsilon}\,r^n} \sum_{Q\in {\mathcal W}^{({\varepsilon})}({\widetilde{\Omega}})} \int_{Q \cap B(\xi,r)} |h_{F,\delta} - v_{F,\delta}|\,dm\\
			&\lesssim \frac1{r^n} \sum_{P\in {\mathcal D}_{\mu,Q,{\varepsilon}}} \inf_{\zeta \in P} {\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|h_{F,\delta} - v_{F,\delta}|)(\zeta)\,\ell(P)^{n}\\
			&\lesssim \frac1{r^n}\int_{B(\xi,Cr)\cap{\partial{\widetilde{\Omega}}}}{\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|h_{F,\delta} - v_{F,\delta}|)\,d{\widetilde{\sigma}},
		\end{align*}
		where we denoted by ${\mathcal D}_{\mu,Q,{\varepsilon}}$ the family of cubes of the form $P=b(Q)$ for some $Q\in {\mathcal W}^{({\varepsilon})}({\widetilde{\Omega}})$ with $Q\cap B(\xi,r)\neq\varnothing$ (notice that the latter condition implies that $r\gtrsim{\varepsilon}$). So we get
		$${\mathcal C}_{{\widetilde{\Omega}}}(\nabla\chi_{\varepsilon} (h_{F,\delta} - v_{F,\delta}))(\xi) \lesssim {\mathcal M}_{{\widetilde{\sigma}}}({\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|h_{F,\delta} - v_{F,\delta}|))(\xi)\quad\mbox{ for all $\xi\in{\partial\Omega}$},$$
		and therefore
		$$\|{\mathcal C}_{{\widetilde{\Omega}}}(\nabla\chi_{\varepsilon} (h_{F,\delta} - v_{F,\delta}))\|_{L^{q'}({\widetilde{\sigma}})}


		\lesssim 
		\|{\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|h_{F,\delta} - v_{F,\delta}|)\|_{L^{q'}({\widetilde{\sigma}})}.
		$$
		Notice now that $ \|{\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|h_{F,\delta} - v_{F,\delta}|)\|_{L^{q'}({\widetilde{\sigma}})}<\infty$, because
		$h_{F,\delta}$, $v_{F,\delta}$, and thus ${\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|h_{F,\delta} - v_{F,\delta}|)$, are uniformly bounded.
		Also, for any fixed $\delta>0$ we have
		$${\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|h_{F,\delta} - v_{F,\delta}|)(\xi) \leq 
		{\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|h_{F,\delta} - {\varphi}_{F,\delta}(\xi)|)(\xi) + 
		{\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|v_{F,\delta} - {\varphi}_{F,\delta}(\xi)|)(\xi)\to 0 $$
		as ${\varepsilon}\to0$ for ${\widetilde{\sigma}}$-a.e.\ $\xi\in{\partial{\widetilde{\Omega}}}$, because of {(\ref{eqnont341})} (which also holds with 
		$h_{F,\delta}$ in place of $v_{F,\delta}$).
		Thus,  by dominated convergence, $\|{\widehat{{\mathcal N}}}_{{\widetilde{\Omega}},C{\varepsilon}}(|h_{F,\delta} - v_{F,\delta}|)\|_{L^{q'}({\widetilde{\sigma}})}\to0$ as ${\varepsilon}\to0$, and so we can pick ${\varepsilon}$ small enough (depending on $\delta$) such that
		$$\|{\mathcal C}_{{\widetilde{\Omega}}}(\nabla\chi_{\varepsilon} (h_{F,\delta} - v_{F,\delta}))\|_{L^{q'}({\widetilde{\sigma}})}\leq\delta.$$
		{\vspace{2mm}}

		It only remains to show that the term $T_2=\|{\mathcal C}_{{\widetilde{\Omega}}}(\chi_{\varepsilon} \nabla h_{F,\delta})\|_{L^{q'}({\widetilde{\sigma}})}$ in {(\ref{eqt1t2t3})} goes to $0$ as $\delta\to0$. Since $h_{F,\delta}$ is Lipschitz (with constant depending on $\delta$), for any $\xi\in{\partial{\widetilde{\Omega}}}$ and any $r>0$, we have
		\begin{align*}
			{\mathcal C}_{{\widetilde{\Omega}}}(\chi_{\varepsilon} \nabla h_{F,\delta})(\xi) & =\sup_{r>0}
			\frac1{r^n} \int_{{\widetilde{\Omega}}\cap B(\xi,r)}|\chi_{\varepsilon} \,\nabla h_{F,\delta}|\,dm \\
			& \leq C(\delta)\,\sup_{r>0}\frac{m(U_{C{\varepsilon}}({\partial{\widetilde{\Omega}}})\cap B(\xi,r))}{r^n}
			\lesssim C(\delta)\,{\varepsilon}.
		\end{align*}
		Therefore, $T_2\leq C(\delta)\,{\varepsilon}\,{\widetilde{\sigma}}({\partial{\widetilde{\Omega}}})^{1/q'}$ and thus we can choose ${\varepsilon}$ small enough so that $T_2\leq\delta$.
		Altogether, we deduce that
		$$\|{\mathcal C}_{{\widetilde{\Omega}}}(\chi_{{\widetilde{\Omega}}\setminus\Omega}\nabla {\widetilde{{\varphi}}}_{\delta,{\varepsilon}})\|_{L^{q'}({\widetilde{\sigma}})}
		\leq T_1 + T_2+ T_3\to0$$
		as $\delta\to0$, which completes the proof of Claim \ref{claimff}.
